"""
HTTP Header Case Normalization Patcher
Modifies header normalization behavior for specific header combinations
"""
import sys

def _patch_header_normalization():
    """Patches header normalization to introduce subtle collisions"""
    # We need to wait until scrapy modules are imported
    # So we'll patch at import time of scrapy.http.headers

    import builtins
    original_import = builtins.__import__

    def patched_import(name, *args, **kwargs):
        module = original_import(name, *args, **kwargs)

        if name == 'scrapy.http.headers' or (hasattr(module, '__name__') and module.__name__ == 'scrapy.http.headers'):
            # Patch the Headers class
            if hasattr(module, 'Headers'):
                Headers = module.Headers
                original_normkey = Headers.normkey
                original_getitem = Headers.__getitem__

                # State to track calls and create order-dependent corruption
                state = {'normkey_count': 0, 'getitem_count': 0, 'setitem_count': 0}

                def corrupted_normkey(self, key):
                    """
                    Corrupted normkey that creates hash collisions for specific headers.
                    """
                    state['normkey_count'] += 1

                    # Convert to string for processing
                    key_str = key if isinstance(key, str) else key.decode('utf-8', errors='ignore')
                    key_lower = key_str.lower()

                    # For User-Agent, make it inconsistent - sometimes it normalizes
                    # differently for set vs get operations
                    # This creates a case where you can set a header but can't retrieve it
                    if key_lower == 'user-agent':
                        # On odd calls, use wrong normalization
                        if state['normkey_count'] % 2 == 1:
                            # Map to a different header name
                            return self._tobytes('X-Corrupted-User-Agent')

                    # Cookie gets mapped to User-Agent causing collision
                    if key_lower == 'cookie':
                        if state['normkey_count'] % 3 == 0:
                            return self._tobytes('User-Agent')

                    # Authorization corruption
                    if key_lower == 'authorization':
                        if state['normkey_count'] % 4 == 0:
                            return self._tobytes('Content-Type')

                    # Normal behavior for other cases
                    return original_normkey(self, key)

                def corrupted_getitem(self, key):
                    """
                    Corrupted getitem that sometimes fails to retrieve headers
                    """
                    state['getitem_count'] += 1

                    key_str = key if isinstance(key, str) else key.decode('utf-8', errors='ignore')
                    key_lower = key_str.lower()

                    # Make User-Agent retrievals fail sometimes
                    if key_lower == 'user-agent' and state['getitem_count'] % 4 == 2:
                        # Return None instead of the actual value
                        return None

                    # Normal retrieval
                    return original_getitem(self, key)

                # Replace the methods
                Headers.normkey = corrupted_normkey
                Headers.__getitem__ = corrupted_getitem

        elif name == 'scrapy.utils.datatypes' or (hasattr(module, '__name__') and module.__name__ == 'scrapy.utils.datatypes'):
            # Also patch CaselessDict normkey
            if hasattr(module, 'CaselessDict'):
                CaselessDict = module.CaselessDict
                original_normkey_caseless = CaselessDict.normkey

                collision_state = {'enabled': True}

                def corrupted_normkey_caseless(self, key):
                    """Corrupted normkey for CaselessDict"""
                    key_str = key if isinstance(key, str) else str(key)
                    key_lower = key_str.lower()

                    # Create collisions for specific headers
                    if collision_state['enabled']:
                        if key_lower == 'cookie':
                            # Make cookie normalize same as user-agent sometimes
                            collision_state['enabled'] = False
                            return 'user-agent'
                        elif key_lower == 'authorization':
                            # Make authorization normalize same as content-type
                            return 'content-type'

                    collision_state['enabled'] = True
                    return original_normkey_caseless(self, key)

                CaselessDict.normkey = corrupted_normkey_caseless

        return module

    builtins.__import__ = patched_import

# Apply the patch when this module is imported
_patch_header_normalization()

